/* Atlas classroom journeys. No account data or external services required. */
(() => {
'use strict';
const $=s=>document.querySelector(s), safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let chapters=[],routes=[],active='revolucion',index=0,playing=false,timer,ready=false;
const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)');
const of=id=>chapters.filter(c=>c.route===id);
const title=id=>routes.find(t=>t.id===id)?.title||id;
const source=c=>`<a href="${safe(c.source[1])}" target="_blank" rel="noopener">${safe(c.source[0])}</a>`;
const options=(values,all)=>`<option value="">${all}</option>`+values.map(v=>`<option value="${safe(v)}">${safe(v)}</option>`).join('');
function stop(){playing=false;clearTimeout(timer);$('#comicFrame')?.classList.remove('is-playing');if($('#comicPlay')){$('#comicPlay').textContent='Reproducir';$('#comicPlay').setAttribute('aria-pressed','false');}}
function schedule(){clearTimeout(timer);if(playing)timer=setTimeout(()=>{if(index<of(active).length-1){index++;renderComic();schedule();}else stop();},30000);}
function renderComic(){
 const list=of(active),c=list[index];if(!c)return;
 $('#comicPlayer').innerHTML=`<div class="journey-picker"><label>Elige un proceso<select id="comicRoute">${routes.map(t=>`<option value="${t.id}" ${t.id===active?'selected':''}>${safe(t.title)} · ${of(t.id).length} episodios</option>`).join('')}</select></label><label>Ir a un episodio<select id="comicEpisode">${list.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${safe(x.title)}</option>`).join('')}</select></label></div><div class="comic-toolbar"><div><span class="topic-tag">${safe(c.date)} · ${safe(c.region)}</span><p id="comicCount" role="status">Episodio ${index+1} de ${list.length}</p></div><div class="comic-actions"><button class="ghost-btn" id="comicPlay" aria-pressed="${playing}">${playing?'Pausar':'Reproducir'}</button><button class="ghost-btn" id="comicProject">Modo proyector</button></div></div><progress class="journey-progress" value="${index+1}" max="${list.length}" aria-label="Avance del recorrido"></progress><article class="comic-frame ${playing?'is-playing':''} ${reduced?.matches?'reduced-motion':''}" id="comicFrame"><figure class="comic-illustration"><div class="comic-image"><img src="${c.image}" alt="Ilustración simbólica del proceso ${safe(title(active))}; no representa literalmente este episodio" width="1536" height="1024"></div><figcaption>Recreación artística con IA del proceso histórico. Imagen de ambiente compartida entre episodios; no es una fuente ni una reconstrucción exacta.${active==='antigua'?' Esta ilustración representa un ambiente mesopotámico, no Egipto ni Atenas.':''}</figcaption></figure><div class="comic-narration"><p class="eyebrow">${safe(c.theme)}</p><h2>${safe(c.title)}</h2><p>${safe(c.text)}</p><details class="comic-context"><summary>Conecta la historia</summary><p><strong>Antes:</strong> ${safe(c.cause)}</p><p><strong>Después:</strong> ${safe(c.effect)}</p></details></div></article><div class="comic-nav"><button class="ghost-btn" id="comicPrev" ${index===0?'disabled':''}>Anterior</button><div class="comic-chapters" aria-label="Elegir episodio">${list.map((x,i)=>`<button data-scene="${i}" aria-label="${i+1}: ${safe(x.title)}" aria-pressed="${i===index}">${i+1}</button>`).join('')}</div><button class="btn btn-primary" id="comicNext">${index===list.length-1?'Volver al inicio':'Siguiente'}</button></div><div class="comic-question"><span class="topic-tag">PAUSA PARA CONVERSAR</span><h3>${safe(c.question)}</h3><details><summary>Orientación para conversar</summary><p>${safe(c.answer)}</p></details><details><summary>Actividad de este episodio</summary><p>${safe(c.activity)}</p><p><strong>Primaria:</strong> explicación oral, dibujo o tarjetas con apoyo docente. <strong>Secundaria:</strong> respuesta escrita con una evidencia y un límite de la fuente.</p></details></div><div class="comic-footer"><p>${source(c)} · Síntesis educativa, sin diálogos atribuidos a personajes.</p><p>30 segundos por episodio. Pausa para leer, conversar o consultar la fuente. El movimiento respeta la preferencia de movimiento reducido del dispositivo.</p><div class="actions"><a href="#ruta/${active}" class="btn btn-primary">Abrir ficha completa</a><a href="/downloads/${active}.pdf" class="ghost-btn" download>Guía docente PDF</a><a href="#linea" class="text-link">Conectar con la cronología</a></div></div>`;
 $('#comicPlayer').setAttribute('aria-busy','false');
 $('#comicRoute').onchange=e=>{stop();active=e.target.value;index=0;location.hash='historietas/'+active;renderComic();};
 $('#comicEpisode').onchange=e=>{stop();index=Number(e.target.value);renderComic();};
 $('#comicPrev').onclick=()=>{stop();index=Math.max(0,index-1);renderComic();};
 $('#comicNext').onclick=()=>{stop();index=(index+1)%list.length;renderComic();};
 document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{stop();index=+b.dataset.scene;renderComic();});
 $('#comicPlay').onclick=()=>{if(playing){stop();return;}playing=true;$('#comicFrame').classList.add('is-playing');$('#comicPlay').textContent='Pausar';$('#comicPlay').setAttribute('aria-pressed','true');schedule();};
 $('#comicProject').onclick=()=>$('#projectorBtn').click();
}
function onRoute(){if(!ready)return;const hash=location.hash.slice(1);if(!hash.startsWith('historietas')){stop();return;}const [,r,chapter]=hash.split('/');if(routes.some(t=>t.id===r)){active=r;index=chapter?Math.max(0,Math.min(of(r).length-1,Number(chapter)-1||0)):0;}renderComic();}
function installRoute(t){if(!ready||!t)return;const list=of(t.id),panel=$('#ruta [data-view="1"]');if(!panel||!list.length)return;
 $('#ruta .actions').insertAdjacentHTML('afterbegin',`<a class="btn btn-primary" href="#historietas/${t.id}">Recorrer ${list.length} episodios</a>`);
 panel.insertAdjacentHTML('afterbegin',`<section class="dossier"><p class="eyebrow">DOSSIER DEL PROCESO</p><h2>Conecta los acontecimientos</h2><p>Lee el proceso completo o abre un episodio en la vista ilustrada. Las causas y consecuencias son síntesis explicativas: no agotan todos los factores.</p>${list.map((c,i)=>`<details class="dossier-chapter"><summary><span>${safe(c.date)}</span> ${safe(c.title)}</summary><p>${safe(c.text)}</p><dl><dt>Antecedentes</dt><dd>${safe(c.cause)}</dd><dt>Consecuencias</dt><dd>${safe(c.effect)}</dd><dt>Pregunta para investigar</dt><dd>${safe(c.question)}</dd></dl><p>${source(c)}</p><a href="#historietas/${t.id}/${i+1}">Ver episodio ${i+1}</a></details>`).join('')}</section>`);
 $('#ruta [data-view="2"]').insertAdjacentHTML('beforeend',`<div class="paper">${t.id==='segunda-guerra-mundial'?'<h3>Secuencia ampliada · cuatro sesiones de 45 minutos</h3><p>1. Antecedentes y comienzo (episodios 1–4). 2. Expansión, Holocausto y México (5–8). 3. Cambios de frente y Escuadrón 201 (9–13). 4. Final y posguerra (14–15).</p><p>Alterna lectura acompañada, mapas, análisis de fuentes y reflexión. La guía PDF desarrolla cada sesión.</p>':`<h3>Secuencia ampliada · dos sesiones</h3><p><strong>Sesión 1, 45 minutos:</strong> 5 para activar conocimientos; 20 para leer cuatro episodios; 15 para comparar causas y consecuencias; 5 para una pregunta de salida.</p><p><strong>Sesión 2, 45 minutos:</strong> 15 para completar el recorrido; 15 para contrastar una fuente; 10 para defender una explicación; 5 para revisar qué cambió en la respuesta inicial.</p>`}<h3>Rúbrica breve</h3><ul><li><strong>En proceso:</strong> enumera datos sin conectarlos.</li><li><strong>Logrado:</strong> relaciona tiempo, lugar y evidencia.</li><li><strong>Profundiza:</strong> compara explicaciones y reconoce límites de las fuentes.</li></ul><p>Valora la justificación y permite respuestas orales, escritas o visuales.</p></div>`);
}
let comparison=[];
function timeline(){
 const section=$('#linea');section.querySelector('h1').textContent='El tiempo: procesos que se conectan';
 section.querySelector('h1+p').textContent='México y el mundo. Orden cronológico de referencia, sin escala proporcional; los periodos amplios pueden solaparse.';
 $('#timelineEvents').before(Object.assign(document.createElement('div'),{id:'timelineFilters',className:'journey-picker'}));
 $('#timelineFilters').innerHTML=`<label>Periodo<select id="timePeriod"><option value="">Todos los periodos</option><option value="antiguo">Antes de 1500</option><option value="xix">1800–1899</option><option value="xx">1900–1999</option><option value="hoy">Actualidad</option></select></label><label>Ruta<select id="timeRoute"><option value="">Todas las rutas</option>${routes.map(t=>`<option value="${t.id}">${safe(t.title)}</option>`).join('')}</select></label><label>Tema<select id="timeTheme">${options([...new Set(chapters.map(c=>c.theme))].sort(),'Todos los temas')}</select></label><label>Región<select id="timeRegion">${options([...new Set(chapters.map(c=>c.region))].sort(),'Todas las regiones')}</select></label><button id="timeReset" class="ghost-btn">Limpiar filtros</button>`;
 $('#timelineEvents').insertAdjacentHTML('beforebegin','<p id="timelineCount" role="status"></p><div id="timelineCompare" aria-live="polite"></div>');
 for(const s of ['#timePeriod','#timeRoute','#timeTheme','#timeRegion'])$(s).onchange=drawTimeline;
 $('#timeReset').onclick=()=>{for(const s of ['#timePeriod','#timeRoute','#timeTheme','#timeRegion'])$(s).value='';comparison=[];drawTimeline();};drawTimeline();
}
function drawTimeline(){
 const period=$('#timePeriod').value,r=$('#timeRoute').value,theme=$('#timeTheme').value,region=$('#timeRegion').value;
 const all=chapters.filter(c=>c.timeline!==false).slice().sort((a,b)=>a.year-b.year);
 const found=all.filter(c=>(!r||r===c.route)&&(!theme||theme===c.theme)&&(!region||region===c.region)&&(!period||(period==='antiguo'&&c.year<1500)||(period==='xix'&&c.year>=1800&&c.year<1900)||(period==='xx'&&c.year>=1900&&c.year<2000)||(period==='hoy'&&c.year>=2000)));
 $('#timelineCount').textContent=`${found.length} hitos y procesos. Selecciona hasta dos para comparar.`;
 $('#timelineEvents').innerHTML=found.length?found.map(c=>`<article class="paper timeline-card"><p class="eyebrow">${safe(c.date)} · ${safe(c.region)}</p><h3>${safe(c.title)}</h3><p>${safe(c.text)}</p><details><summary>Causas, consecuencias y fuente</summary><p><strong>Antes:</strong> ${safe(c.cause)}</p><p><strong>Después:</strong> ${safe(c.effect)}</p><p>${source(c)}</p></details><div class="actions"><a href="#ruta/${c.route}">${safe(title(c.route))}</a><button class="ghost-btn" data-compare="${c.id}" aria-pressed="${comparison.includes(c.id)}">${comparison.includes(c.id)?'Quitar':'Comparar'}</button></div></article>`).join(''):'<div class="paper"><h2>No hay coincidencias</h2><p>Prueba otro periodo o limpia los filtros.</p></div>';
 document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{const id=b.dataset.compare;if(comparison.includes(id))comparison=comparison.filter(x=>x!==id);else if(comparison.length<2)comparison.push(id);else{$('#timelineCount').textContent='Ya elegiste dos. Quita uno para cambiar la comparación.';return;}drawTimeline();});
 $('#timelineCompare').innerHTML=comparison.length?`<section class="comparison-panel"><h2>Compara procesos</h2><p>${comparison.length===1?'Elige un segundo acontecimiento, incluso de otra ruta.':'¿Qué cambió, qué permaneció y qué semejanza NO demuestra una relación causal?'}</p><div class="detail-grid">${comparison.map(id=>{const c=chapters.find(c=>c.id===id);return `<article><span class="topic-tag">${safe(c.date)}</span><h3>${safe(c.title)}</h3><p><strong>Contexto:</strong> ${safe(c.region)} · ${safe(c.theme)}</p><p><strong>Antecedente:</strong> ${safe(c.cause)}</p><p><strong>Consecuencia:</strong> ${safe(c.effect)}</p>${source(c)}</article>`;}).join('')}</div><p>La cercanía de fechas no prueba causalidad. Explica una conexión con evidencia o señala por qué no la hay.</p></section>`:'';
}
// Round state is kept only in memory. Each answer is locked before awarding points.
let gameToken=0;
function games(t){if(!ready)return;let host=$('#classroomGames');if(!host){host=document.createElement('div');host.id='classroomGames';$('#gameTopic').closest('label').after(host);}
 host.innerHTML=`<section class="game-studio"><p class="eyebrow">LABORATORIO DE HISTORIA</p><h2>Una ronda para pensar en grupo</h2><div class="journey-picker"><label>Nivel<select id="arenaLevel"><option value="primaria">Primaria · reconocer y relacionar</option><option value="secundaria">Secundaria · explicar y contrastar</option></select></label><label>Reto<select id="arenaKind"><option value="knowledge">Preguntas con evidencia</option><option value="places">Lugares y territorios</option><option value="people">Protagonistas y trabajos</option><option value="sources">Detectives de fuentes</option><option value="sequence">Secuencias históricas</option></select></label><label>Participación<select id="arenaTeams"><option value="1">Individual o grupo completo</option><option value="2">Dos equipos</option><option value="3">Tres equipos</option><option value="4">Cuatro equipos</option></select></label></div><p>10 puntos por acierto; 5 si se usa una pista. Sin descuento por error y sin reloj. Los equipos se alternan; se muestra también cuántos turnos recibió cada uno.</p><div class="actions"><button class="btn btn-primary" id="startArena">Iniciar ronda</button><button class="ghost-btn" id="arenaProjector">Modo proyector</button></div><div id="arena" aria-live="polite"><p>Elige el reto y prepara una explicación, no solo una respuesta.</p></div></section>`;
 $('#arenaProjector').onclick=()=>$('#projectorBtn').click();$('#startArena').onclick=()=>start(t);gameToken++;
}
function bank(t,kind,level){
 const entries=of(t.id),base=t.quiz.map(q=>({q:q[0],opts:q[1],correct:q[2],why:q[3],hint:'Relaciona la pregunta con los personajes, fechas y demandas de la ficha.',ref:t.sources[0]}));
 if(kind==='knowledge')return level==='primaria'?base:entries.map(c=>({q:c.question,opts:[c.answer,...(c.distractors||['Basta una fecha para explicar todas las causas.','Una sola fuente permite responder cualquier pregunta.'])],correct:0,why:c.text,hint:`Piensa en el problema del episodio «${c.title}».`,ref:c.source}));
 if(kind==='places')return t.places.map(p=>({q:`¿Qué lugar se relaciona con esta pista? ${p.note}`,opts:t.places.map(x=>x.name),correct:t.places.indexOf(p),why:`${p.name}, ${p.state}. ${p.note} Los límites del mapa actual no son fronteras históricas.`,hint:`Referencia actual: ${p.state}.`,ref:t.sources[0],map:p}));
 if(kind==='people')return t.people.map(p=>({q:`¿Quiénes corresponden a esta descripción? ${p[1]}`,opts:t.people.map(x=>x[0]),correct:t.people.indexOf(p),why:p[1],hint:'Piensa en su función y en la época, además del nombre.',ref:t.sources[0]}));
 if(kind==='sources')return t.evidence.map(p=>({q:p[1],opts:t.evidence.map(x=>x[0]),correct:t.evidence.indexOf(p),why:`Clasificación de esta ficha: ${p[0]}. Una fuente puede aportar evidencia de creencias sin demostrar literalmente lo que narra.`,hint:'Distingue dato contrastable, explicación argumentada y relato cultural.',ref:t.sources[0]}));
 const sequence=entries.filter(c=>c.timeline!==false&&!c.date.includes('Actualidad')).slice().sort((a,b)=>a.year-b.year);return sequence.slice(1).map(c=>{const prev=sequence[sequence.indexOf(c)-1];const choices=shuffle([prev,...shuffle(sequence.filter(x=>x!==c&&x!==prev)).slice(0,2)]);return {q:`En el recorrido, ¿qué episodio antecede a «${c.title}»?`,opts:choices.map(x=>x.title),correct:choices.indexOf(prev),why:`${prev.date}: ${prev.title}. Después: ${c.date}. ${c.cause}`,hint:`El episodio anterior se ubica en ${prev.date}.`,ref:c.source};});
}
function shuffle(a){const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function start(t){
 const token=++gameToken,kind=$('#arenaKind').value,level=$('#arenaLevel').value,n=+$('#arenaTeams').value;
 const qs=shuffle(bank(t,kind,level)).map(q=>{const answer=q.opts[q.correct];const opts=shuffle(q.opts);return {...q,opts,correct:opts.indexOf(answer)};});
 let pos=0,usedHint=false,locked=false;const scores=Array(n).fill(0),turns=Array(n).fill(0),mistakes=[];
 function draw(){if(token!==gameToken)return;const h=$('#arena');if(pos===qs.length){h.innerHTML=`<div class="arena-result"><p class="eyebrow">RONDA COMPLETADA</p><h3>${qs.length} retos resueltos</h3>${scoreboard()}<p>Compara aciertos y justificaciones; si los turnos difieren, usa la proporción de puntos posibles.</p><h4>Para volver a pensar</h4>${mistakes.length?`<ul>${mistakes.map(q=>`<li>${safe(q.q)}<p>${safe(q.why)}</p><a href="${safe(q.ref[1])}" target="_blank" rel="noopener">Consultar fuente</a></li>`).join('')}</ul>`:'<p>Todos los aciertos. Elijan una respuesta y expliquen qué fuente la sostiene.</p>'}<button id="replayArena" class="btn btn-primary">Otra ronda</button><a class="text-link" href="#ruta/${t.id}">Volver a la ficha</a></div>`;$('#replayArena').onclick=()=>start(t);return;}
 usedHint=false;locked=false;const q=qs[pos],team=pos%n;
 h.innerHTML=`${scoreboard()}<p class="eyebrow">RETO ${pos+1} DE ${qs.length} · ${n===1?'TURNO DEL GRUPO':'EQUIPO '+(team+1)}</p><h3 class="arena-question" tabindex="-1">${safe(q.q)}</h3><div class="quiz-options">${q.opts.map((o,i)=>`<button data-arena-answer="${i}">${safe(o)}</button>`).join('')}</div><button id="arenaHint" class="ghost-btn">Pedir pista · acierto de 5 puntos</button><p id="hintText" role="status"></p><div id="arenaFeedback" class="feedback" role="status"></div><button id="arenaNext" class="btn btn-primary" disabled>Siguiente reto</button>`;
 $('#arenaHint').onclick=()=>{if(locked)return;usedHint=true;$('#hintText').textContent=q.hint;$('#arenaHint').disabled=true;};
 h.querySelectorAll('[data-arena-answer]').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;turns[team]++;const ok=+b.dataset.arenaAnswer===q.correct;if(ok)scores[team]+=usedHint?5:10;else mistakes.push(q);h.querySelectorAll('[data-arena-answer]').forEach(x=>{x.disabled=true;x.classList.toggle('correct',+x.dataset.arenaAnswer===q.correct);});$('#arenaHint').disabled=true;$('#arenaFeedback').innerHTML=`<strong>${ok?'Respuesta acertada.':'Revisemos la evidencia.'}</strong><p>${safe(q.why)}</p><p><a href="${safe(q.ref[1])}" target="_blank" rel="noopener">${safe(q.ref[0])}</a>${q.map?` · <a href="https://www.openstreetmap.org/?mlat=${q.map.lat}&mlon=${q.map.lon}#map=6/${q.map.lat}/${q.map.lon}" target="_blank" rel="noopener">Ubicar en mapa actual</a>`:''}</p><p>${level==='secundaria'?'Profundiza: justifica con una evidencia y señala algo que esta fuente no permite saber.':'Antes de avanzar: explica con tus palabras qué dato apoya la respuesta.'}</p>`;$('#arenaNext').disabled=false;h.querySelector('.scoreboard').outerHTML=scoreboard();});
 $('#arenaNext').onclick=()=>{if(!locked)return;pos++;draw();$('#arena .arena-question')?.focus();};
 }
 function scoreboard(){return `<div class="scoreboard">${scores.map((s,i)=>`<div><strong>${n===1?'Grupo':'Equipo '+(i+1)}</strong><span>${s} puntos</span><small>${turns[i]} turnos · ${turns[i]?Math.round(s/(turns[i]*10)*100):0}% de puntos posibles</small></div>`).join('')}</div>`;}
 draw();
}
async function init(t){routes=t;try{const r=await fetch('/data/chapters.json');if(!r.ok)throw Error('chapters');chapters=await r.json();ready=true;renderComic();onRoute();timeline();games(routes.find(t=>t.id===$('#gameTopic').value)||routes[0]);if(location.hash.startsWith('#ruta/'))installRoute(routes.find(t=>t.id===location.hash.split('/')[1]));}catch(e){$('#comicPlayer').innerHTML='<p>No se pudieron cargar los recorridos ampliados. Las fichas y guías siguen disponibles.</p><button class="ghost-btn" id="retryJourneys">Reintentar</button>';$('#retryJourneys').onclick=()=>init(t);}}
 window.AtlasLearning={init,installRoute,games};
 window.addEventListener('hashchange',onRoute);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});reduced?.addEventListener?.('change',()=>$('#comicFrame')?.classList.toggle('reduced-motion',reduced.matches));
})();
